mapper.sql:
WHERE employee_calendars.is_active = 1
AND employee_calendars.employee_id = #{filter.employeeId}
AND DATE(employee_calendars.date_to) >= DATE(#{filter.dateFrom})
AND DATE(employee_calendars.date_from) <= DATE(#{filter.dateTo})
AND employee_calendars.is_repeatable = #{filter.isRepeatable}
AND employee_calendars.repeat_type = #{filter.repeatType}
AND ( employees.code LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.name LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR departments.name LIKE CONCAT("%", #{filter.searchText}, "%") OR employee_calendars.description LIKE CONCAT("%", #{filter.searchText}, "%") OR CAST(employee_calendars.date_from AS CHAR) LIKE CONCAT("%", #{filter.searchText}, "%") OR CAST(employee_calendars.date_to AS CHAR) LIKE CONCAT("%", #{filter.searchText}, "%") OR EXISTS ( SELECT 1 FROM employee_calendar_details WHERE employee_calendar_details.employee_calendar_id = employee_calendars.id AND employee_calendar_details.repeat_days LIKE CONCAT("%", #{filter.searchText}, "%") ) OR EXISTS ( SELECT 1 FROM employee_calendar_details INNER JOIN customer_markets ON customer_markets.id = employee_calendar_details.market_id WHERE employee_calendar_details.employee_calendar_id = employee_calendars.id AND customer_markets.is_active = 1 AND customer_markets.name LIKE CONCAT("%", #{filter.searchText}, "%") ) )

mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    employee_calendars.date_from DESC, employee_calendars.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.insert:
INSERT INTO employee_calendar_details (
  employee_calendar_id,
  market_id,
  repeat_days
) VALUES (
  #{employeeCalendarId},
  #{marketId},
  #{repeatDay}
)
